//! JSON Schema (draft 2020-12) of the contract, generated by schemars (ADR-R2-2).
//!
//! The committed copy is `schema/coaching-input-v1.schema.json`; `tests/parity.rs` keeps it
//! current and compares its shape with the zod export in `fixtures/coaching-input/ts-schema.json`.

use schemars::generate::SchemaSettings;
use schemars::transform::RecursiveTransform;
use schemars::{Schema, SchemaGenerator, json_schema};
use serde_json::Value;

use crate::limits::{DATE_PATTERN, DATETIME_MAX_CHARS, DATETIME_PATTERN, UUID_PATTERN};
use crate::types::CoachingInput;

/// schemars' Rust-only number formats (`"format": "uint32"` and so on). They are annotations
/// that zod does not emit and strict validators (Ajv) reject as unknown, so they are dropped.
const RUST_NUMBER_FORMATS: &[&str] = &[
    "int8", "int16", "int32", "int64", "int128", "int", "uint8", "uint16", "uint32", "uint64",
    "uint128", "uint", "float", "double",
];

/// The contract's JSON Schema.
pub fn json_schema() -> Value {
    SchemaSettings::draft2020_12()
        .with_transform(RecursiveTransform(contract_transform))
        .into_generator()
        .into_root_schema_for::<CoachingInput>()
        .to_value()
}

/// Applied to every subschema. schemars makes a plain `Option` field optional (absent allowed);
/// zod objects have no optional keys, so every property of every object becomes required while
/// an `Option` keeps its `null` alternative. `required` is sorted so the output does not depend
/// on serde_json's map order. Also drops [`RUST_NUMBER_FORMATS`].
pub fn contract_transform(schema: &mut Schema) {
    if let Some(Value::Object(properties)) = schema.get("properties") {
        let mut required: Vec<String> = properties.keys().cloned().collect();
        required.sort();
        schema.insert(
            "required".into(),
            Value::Array(required.into_iter().map(Value::String).collect()),
        );
    }
    if let Some(Value::String(format)) = schema.get("format")
        && RUST_NUMBER_FORMATS.contains(&format.as_str())
    {
        schema.remove("format");
    }
}

/// zod `z.iso.datetime().max(40)`: UTC with a `Z` suffix (`common::js_time::iso` output).
pub fn iso_datetime(_: &mut SchemaGenerator) -> Schema {
    json_schema!({
        "type": "string",
        "maxLength": DATETIME_MAX_CHARS,
        "format": "date-time",
        "pattern": DATETIME_PATTERN,
    })
}

/// zod `z.iso.date()`: `YYYY-MM-DD`.
pub fn iso_date(_: &mut SchemaGenerator) -> Schema {
    json_schema!({
        "type": "string",
        "format": "date",
        "pattern": DATE_PATTERN,
    })
}

/// zod `z.uuid()`: an RFC 9562 UUID (version 1-8, variant 10xx) or the nil or max UUID.
pub fn uuid(_: &mut SchemaGenerator) -> Schema {
    json_schema!({
        "type": "string",
        "format": "uuid",
        "pattern": UUID_PATTERN,
    })
}
